import java.util.*;

public class Main {
    public static void main(String[] args) {
        Queue<Integer> q = new ArrayDeque<>();
        for (int i = 1; i <= 4; i++) q.offer(i);
        while (q.size() > 1) {
            q.offer(q.poll());
            q.poll();
        }
        System.out.println(q.peek());
    }
}

