import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        ArrayDeque<Integer> q = new ArrayDeque<>();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < n; i++) {
            String[] p = br.readLine().trim().split(" ");
            if (p[0].equals("ENQ")) q.addLast(Integer.parseInt(p[1]));
            else if (p[0].equals("DEQ")) sb.append(q.isEmpty() ? "EMPTY" : String.valueOf(q.pollFirst())).append('\n');
            else if (p[0].equals("FRONT")) sb.append(q.isEmpty() ? "EMPTY" : String.valueOf(q.peekFirst())).append('\n');
            else sb.append(q.size()).append('\n');
        }
        System.out.print(sb);
    }
}
